@font-face{font-family:NotoSansSC;src:url("data:font/woff2;base64,") format("woff2");font-weight:400}
@font-face{font-family:NotoSansSC;src:url("data:font/woff2;base64,") format("woff2");font-weight:600}
@font-face{font-family:NotoSerifSC;src:url("__FONT_SERIF_600__") format("woff2");font-weight:600}
:root{--paper:#f7f5ef;--ink:#262d31;--muted:#667176;--rule:#bdc5c3;--tint:#e9eeeb;--accent:#0b6b66;--accent-soft:#d8e7e3;--font-body:10.75pt;--font-source:7.5pt}
*{box-sizing:border-box}html,body{margin:0;background:#dfe3e1;color:var(--ink);font-family:NotoSansSC,Arial,sans-serif;font-size:var(--font-body);line-height:1.58;font-variant-numeric:tabular-nums}body{padding:12mm 0}
@page{size:210mm 297mm;margin:0}
.page{position:relative;width:210mm;height:297mm;margin:0 auto 10mm;background:var(--paper);padding:18mm 17mm 18mm 20mm;overflow:hidden;break-after:page;page-break-after:always}
.page:last-child{break-after:auto}.eyebrow{font-size:8pt;letter-spacing:.13em;text-transform:uppercase;color:var(--accent);font-weight:600}.folio{position:absolute;right:17mm;bottom:5.5mm;font-size:8pt;color:var(--muted)}.running{display:flex;justify-content:space-between;border-bottom:.35pt solid var(--rule);padding-bottom:2.5mm;margin-bottom:7mm;font-size:7.8pt;color:var(--muted)}
h1,h2,h3,p{margin:0}h1,h2{font-family:NotoSerifSC,serif;font-weight:600}h1{font-size:26pt;line-height:1.22;max-width:152mm}h2{font-size:20pt;line-height:1.35;margin:2mm 0 7mm;max-width:165mm}h3{font-size:12pt;line-height:1.45}.deck{font-size:12pt;line-height:1.7;color:#485459;max-width:146mm}.kicker{font-size:9pt;color:var(--muted);margin-bottom:2mm}.label{font-size:7.7pt;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);font-weight:600}.source{position:absolute;left:20mm;right:17mm;bottom:12mm;border-top:.35pt solid var(--rule);padding-top:2mm;font-size:var(--font-source);line-height:1.34;color:var(--muted);overflow-wrap:anywhere}.takeaway{font-weight:600;border-left:2.2mm solid var(--accent);padding-left:4mm;font-size:11.5pt;line-height:1.55}.note{font-size:8.5pt;line-height:1.45;color:var(--muted)}.synthetic{display:inline-block;border:.45pt solid var(--accent);color:var(--accent);font-size:7pt;line-height:1;padding:1.2mm 1.8mm;letter-spacing:.06em;font-weight:600}.rule{height:.45pt;background:var(--rule);margin:5mm 0}.accent{color:var(--accent)}
.cover{padding-top:34mm}.cover-mark{width:16mm;height:2.2mm;background:var(--accent);margin-bottom:28mm}.cover h1{font-size:32pt;max-width:150mm}.cover .deck{margin-top:9mm}.cover-meta{position:absolute;left:20mm;right:17mm;bottom:29mm;display:grid;grid-template-columns:1fr 1fr;border-top:.6pt solid var(--ink);padding-top:4mm;font-size:9pt}.cover-meta div:last-child{text-align:right}
.toc-grid{display:grid;grid-template-columns:38mm 1fr;gap:10mm;margin-top:14mm}.toc-no{font-family:NotoSerifSC;font-size:26pt;color:var(--accent)}.toc-list{border-top:.7pt solid var(--ink)}.toc-item{display:grid;grid-template-columns:1fr 15mm;padding:5mm 0;border-bottom:.35pt solid var(--rule)}.toc-item strong{font-size:12pt}.toc-item span:last-child{text-align:right;color:var(--accent)}
.summary-grid{display:grid;grid-template-columns:1.4fr .75fr;gap:12mm;counter-reset:d}.thesis{font-family:NotoSerifSC;font-size:17pt;line-height:1.5;margin-bottom:8mm}.decision{display:grid;grid-template-columns:10mm 1fr;gap:3mm;padding:4.5mm 0;border-top:.4pt solid var(--rule)}.decision:before{counter-increment:d;content:"0" counter(d);color:var(--accent);font-weight:600}.decision p{font-size:9.6pt}.metric-rail{border-left:.8pt solid var(--rule);padding-left:7mm}.big{font-family:NotoSerifSC;font-size:30pt;line-height:1;color:var(--accent);margin:2mm 0}.metric{margin-bottom:9mm}
.section-page{display:flex;flex-direction:column;justify-content:center}.section-no{font-family:NotoSerifSC;font-size:72pt;color:var(--accent-soft);line-height:1}.section-page h1{font-size:28pt;margin-top:-9mm}.section-page .takeaway{margin-top:14mm;max-width:135mm}
.split{display:grid;grid-template-columns:1.42fr .72fr;gap:10mm}.exhibit{min-height:126mm}.chart-title{font-weight:600;margin-bottom:2mm}.chart-sub{font-size:8.3pt;color:var(--muted);margin-bottom:4mm}.bar-row{display:grid;grid-template-columns:34mm 1fr 18mm;align-items:center;gap:3mm;margin:5mm 0}.bar-track{height:7mm;background:#e1e5e2}.bar{height:100%;background:var(--accent)}.bar-row:nth-child(even) .bar{background:#647a77}.num{text-align:right;font-weight:600}.side-argument{padding-top:8mm}.side-argument h3{margin:0 0 2mm}.side-argument p{font-size:9pt;margin-bottom:7mm}
.chart-table{display:grid;grid-template-columns:1.05fr .95fr;gap:9mm;align-items:start}.waterfall{display:flex;align-items:flex-end;height:90mm;border-bottom:.6pt solid var(--ink);padding:0 2mm;gap:3mm}.wf{width:15mm;background:var(--accent);position:relative;flex:0 1 15mm}.wf.alt{background:#82928f}.wf.loss{background:repeating-linear-gradient(135deg,#869390 0,#869390 2px,#e7eae7 2px,#e7eae7 5px)}.wf span{position:absolute;top:-7mm;width:100%;text-align:center;font-weight:600}.wf small{position:absolute;bottom:-12mm;width:100%;text-align:center;font-size:7.4pt;line-height:1.2}table{width:100%;border-collapse:collapse;font-size:8.5pt;line-height:1.35}th{text-align:left;background:var(--tint);font-weight:600;border-top:.7pt solid var(--ink)}th,td{padding:2.7mm 2mm;border-bottom:.35pt solid var(--rule);vertical-align:top}td.num,th.num{text-align:right}.em-row td{font-weight:600;color:var(--accent)}
.matrix{display:grid;grid-template-columns:35mm repeat(3,1fr);border-top:.7pt solid var(--ink);border-left:.35pt solid var(--rule)}.cell{min-height:25mm;padding:4mm;border-right:.35pt solid var(--rule);border-bottom:.35pt solid var(--rule);font-size:8.7pt}.cell.head{min-height:auto;background:var(--tint);font-weight:600}.cell.best{background:var(--accent-soft)}.score{font-family:NotoSerifSC;font-size:20pt;color:var(--accent);display:block;margin-top:2mm}
.quote-layout{display:grid;grid-template-columns:.8fr 1.35fr;gap:11mm}.quote-mark{font-family:NotoSerifSC;font-size:60pt;color:var(--accent-soft);line-height:.7}.quote{font-family:NotoSerifSC;font-size:17pt;line-height:1.6}.evidence-notes{border-left:.7pt solid var(--rule);padding-left:8mm}.evidence-notes dl{margin:0}.evidence-notes dt{font-weight:600;color:var(--accent);margin-top:5mm}.evidence-notes dd{margin:1mm 0;font-size:9pt}
.heatmap{display:grid;grid-template-columns:38mm repeat(4,1fr);margin-top:6mm}.heatmap div{padding:5mm 3mm;border-right:1mm solid var(--paper);border-bottom:1mm solid var(--paper);font-size:8.5pt;text-align:center}.heatmap .rowhead{text-align:left;font-weight:600;background:transparent}.heatmap .h1{background:#eef0ec}.heatmap .h2{background:#d8e7e3}.heatmap .h3{background:#9fc2bc}.heatmap .h4{background:#4c8c86;color:white}.legend{display:flex;gap:3mm;align-items:center;margin-top:4mm;font-size:8pt}.swatch{width:8mm;height:3mm;background:repeating-linear-gradient(135deg,#4c8c86 0,#4c8c86 2px,#eef0ec 2px,#eef0ec 4px)}
.dense-table{font-size:7.8pt;line-height:1.28}.dense-table th,.dense-table td{padding:2.35mm 1.7mm}.continued{float:right;color:var(--accent);font-size:8pt}.status{font-size:7pt;font-weight:600;white-space:nowrap}.status.high{border-bottom:2px double var(--ink)}.status.mid{border-bottom:2px dashed var(--ink)}.status.low{border-bottom:1px solid var(--ink)}
.risk-map{position:relative;height:128mm;border-left:.6pt solid var(--ink);border-bottom:.6pt solid var(--ink);margin:4mm 18mm 0 18mm;background:linear-gradient(to right,transparent 49.8%,var(--rule) 50%,transparent 50.2%),linear-gradient(to bottom,transparent 49.8%,var(--rule) 50%,transparent 50.2%)}.risk-dot{position:absolute;width:29mm;height:18mm;border:.6pt solid var(--accent);background:var(--paper);padding:2mm;font-size:8pt;font-weight:600}.risk-dot:before{content:"";display:inline-block;width:3mm;height:3mm;background:var(--accent);margin-right:2mm}.axis-x{margin-left:18mm;text-align:right;font-size:8pt}.axis-y{position:absolute;left:5mm;top:105mm;transform:rotate(-90deg);font-size:8pt}
.roadmap{position:relative;margin-top:12mm}.stage{position:relative;display:grid;grid-template-columns:34mm 1fr 42mm;gap:7mm;margin-bottom:8mm;padding:4mm 0;border-bottom:.35pt solid var(--rule)}.stage-no{font-family:NotoSerifSC;font-size:23pt;color:var(--accent);background:var(--paper);z-index:1}.gate{border-left:1.4mm solid var(--accent);padding-left:4mm;font-size:8.3pt}.stage p{font-size:9pt}
.refs{counter-reset:ref}.ref{display:grid;grid-template-columns:9mm 1fr;gap:3mm;padding:3.4mm 0;border-bottom:.35pt solid var(--rule);font-size:8.3pt;break-inside:avoid}.ref:before{counter-increment:ref;content:"[" counter(ref) "]";color:var(--accent);font-weight:600}.url{font-size:7.5pt;color:var(--muted);overflow-wrap:anywhere}.method-box{margin-top:8mm;border-top:.7pt solid var(--ink);padding-top:4mm;display:grid;grid-template-columns:1fr 1fr;gap:8mm;font-size:8.5pt}
@media print{html,body{background:transparent}body{padding:0}.page{margin:0;box-shadow:none}}
